+test("cooking bechamel uses the milk that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: HD-1022 (batch 4, 2 l, expires first) and HD-1026 (batch 3, 8 l, newer).
+  const result = cook(store, 2, 10, { at });
