+  const store = fresh();
+  const mk = (id, expires, receivedOn) => ({ id, itemId: 2, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "fridge" });
+  store.data.batches = store.data.batches.filter((b) => b.itemId !== 2);
+  store.data.batches.push(
+    mk(101, null, "2026-10-01"),
+    mk(102, "2026-11-10", "2026-10-20"),
+    mk(103, "2026-11-10", "2026-10-10"),
